mapper.select:
SELECT COALESCE(SUM(ms.total_cost), 0) AS bill , ym.`year_month` AS yearMonth , 'AWS' AS csp FROM (
SELECT #{prevMonth} COLLATE utf8mb4_unicode_ci AS `year_month`
) AS ym LEFT JOIN ( SELECT ms.`year_month` , SUM(ms.total_cost) AS total_cost FROM monthly_summation ms WHERE ms.csp = 'AWS' AND ms.project_cd IN
#{selectedProject}
AND 1=0
AND ms.`year_month` IN
#{prevMonth}
GROUP BY ms.`year_month` ) ms ON ym.`year_month` = ms.`year_month` GROUP BY ym.`year_month`
UNION ALL
SELECT COALESCE(SUM(ncp_data.bill), 0) AS bill , ncp_data.yearMonth AS yearMonth , 'NCP' AS csp FROM ( -- VM (ncp_cost_vm_month) SELECT nvd_latest.demand_month COLLATE utf8mb4_unicode_ci AS yearMonth , SUM(nvd_latest.demand_amount) / ${krwPerUsd} AS bill FROM ( SELECT n1.demand_month, n1.instance_no, n1.demand_amount FROM ncp_cost_vm_month n1 INNER JOIN ( SELECT demand_month, instance_no, MAX(id) AS latest_id FROM ncp_cost_vm_month WHERE demand_month IN
#{prevMonth}
GROUP BY demand_month, instance_no ) n2 ON n1.demand_month = n2.demand_month AND n1.instance_no = n2.instance_no AND n1.id = n2.latest_id ) nvd_latest INNER JOIN servicegroup_meta sm ON nvd_latest.instance_no COLLATE utf8mb4_unicode_ci = sm.csp_instanceid COLLATE utf8mb4_unicode_ci AND sm.csp_type = 'NCP' WHERE 1=1
AND sm.service_cd IN
#{selectedProject}
GROUP BY nvd_latest.demand_month
UNION ALL
-- K8S/Object Storage (ncp_cost_resource_month, 자원·상세코드·계약별 최신 스냅샷) SELECT nr_latest.demand_month COLLATE utf8mb4_unicode_ci AS yearMonth , SUM(nr_latest.demand_amount) / ${krwPerUsd} AS bill FROM ( SELECT n1.demand_month, n1.resource_id, n1.demand_amount FROM ncp_cost_resource_month n1 INNER JOIN ( SELECT demand_month, resource_id, demand_type_detail_code, contract_no, MAX(id) AS latest_id FROM ncp_cost_resource_month WHERE demand_month IN
#{prevMonth}
GROUP BY demand_month, resource_id, demand_type_detail_code, contract_no ) n2 ON n1.demand_month = n2.demand_month AND n1.resource_id = n2.resource_id AND n1.demand_type_detail_code = n2.demand_type_detail_code AND n1.contract_no = n2.contract_no AND n1.id = n2.latest_id AND n1.resource_type != 'OBJECT_STORAGE' -- Object Storage 는 계정 단위 블록(D-4)에서 집계 ) nr_latest INNER JOIN servicegroup_meta sm ON nr_latest.resource_id COLLATE utf8mb4_unicode_ci = sm.csp_instanceid COLLATE utf8mb4_unicode_ci AND sm.csp_type = 'NCP' WHERE 1=1
AND sm.service_cd IN
#{selectedProject}
GROUP BY nr_latest.demand_month
UNION ALL
-- D-4: NCP Object Storage — 계정 단위(OSSM) 행, 최신 누적 스냅샷, Tumblebug OBJECT_STORAGE 메타가 있을 때만 1회 포함 SELECT nro.demand_month COLLATE utf8mb4_unicode_ci AS yearMonth , SUM(nro.demand_amount) / ${krwPerUsd} AS bill FROM ( SELECT o1.resource_id, o1.resource_type, o1.member_no, o1.demand_month, o1.demand_amount FROM ncp_cost_resource_month o1 INNER JOIN ( SELECT demand_month, resource_id, demand_type_detail_code, contract_no, MAX(id) AS latest_id FROM ncp_cost_resource_month WHERE demand_month IN
#{prevMonth}
AND resource_type = 'OBJECT_STORAGE' GROUP BY demand_month, resource_id, demand_type_detail_code, contract_no ) o2 ON o1.demand_month = o2.demand_month AND o1.resource_id = o2.resource_id AND o1.demand_type_detail_code = o2.demand_type_detail_code AND o1.contract_no = o2.contract_no AND o1.id = o2.latest_id ) nro WHERE nro.resource_type = 'OBJECT_STORAGE' AND EXISTS (SELECT 1 FROM servicegroup_meta smo WHERE smo.csp_type = 'NCP' AND smo.service_type = 'OBJECT_STORAGE'
AND smo.service_cd IN
#{selectedProject}
) GROUP BY nro.demand_month ) ncp_data WHERE 1=1
AND 1=0
GROUP BY ncp_data.yearMonth
UNION ALL
SELECT COALESCE(SUM(cost), 0) AS bill , yearMonth , 'AZURE' AS csp FROM (
SELECT COALESCE(SUM(acvd.pre_tax_cost), 0) / ${krwPerUsd} AS cost , #{prevMonth} AS yearMonth FROM azure_cost_vm_daily acvd INNER JOIN servicegroup_meta sm ON acvd.resource_id COLLATE utf8mb4_unicode_ci = sm.csp_instanceid COLLATE utf8mb4_unicode_ci AND sm.csp_type = 'AZURE'
AND sm.service_cd IN
#{selectedProject}
WHERE DATE_FORMAT(acvd.usage_date, '%Y%m') = #{prevMonth} UNION ALL -- K8S/Object Storage (azure_cost_resource_daily) SELECT COALESCE(SUM(acr.pre_tax_cost), 0) / ${krwPerUsd} AS cost , #{prevMonth} AS yearMonth FROM azure_cost_resource_daily acr INNER JOIN servicegroup_meta sm ON LOWER(acr.resource_id) COLLATE utf8mb4_unicode_ci = LOWER(sm.csp_instanceid) COLLATE utf8mb4_unicode_ci AND sm.csp_type = 'AZURE' AND acr.resource_type != 'OBJECT_STORAGE' -- Object Storage 는 계정 단위 블록(D-4)에서 집계
AND sm.service_cd IN
#{selectedProject}
WHERE DATE_FORMAT(acr.usage_date, '%Y%m') = #{prevMonth} UNION ALL -- D-4: Azure Object Storage — Storage Account 단위 행(계정 매핑 ${azureObjStgAccounts}), Tumblebug OBJECT_STORAGE 메타가 있을 때만 1회 포함 SELECT COALESCE(SUM(acr.pre_tax_cost), 0) / ${krwPerUsd} AS cost , #{prevMonth} AS yearMonth FROM azure_cost_resource_daily acr WHERE acr.resource_type = 'OBJECT_STORAGE' AND LOWER(acr.resource_name) IN (${azureObjStgAccounts}) AND DATE_FORMAT(acr.usage_date, '%Y%m') = #{prevMonth} AND EXISTS (SELECT 1 FROM servicegroup_meta smo WHERE smo.csp_type = 'AZURE' AND smo.service_type = 'OBJECT_STORAGE'
AND smo.service_cd IN
#{selectedProject}
)
) AS azure_data WHERE 1=1
AND 1=0
GROUP BY yearMonth
UNION ALL
SELECT COALESCE(SUM(ms.total_cost), 0) AS bill , ms.`year_month` AS yearMonth , 'GCP' AS csp FROM monthly_summation ms WHERE ms.csp = 'GCP' AND ms.project_cd IN
#{selectedProject}
AND ms.`year_month` IN
#{prevMonth}
AND 1=0
GROUP BY ms.`year_month`
ORDER BY yearMonth DESC, csp

SELECT co.lineitem_usageaccountid AS accountID , co.lineitem_productcode AS productID , sm.csp_type AS csp , SUM(co.lineitem_unblendedcost) AS bill , co.lineitem_resourceid AS resourceID FROM tbl_table_billing_detail_${year_month} co INNER JOIN ( SELECT DISTINCT csp_instanceid, csp_type, service_cd FROM servicegroup_meta WHERE csp_type = 'AWS' ) sm ON co.lineitem_resourceid = sm.csp_instanceid
AND sm.service_cd IN
#{selectedProject}
AND co.lineitem_usagestartdate >= #{curMonthStartDate} AND co.lineitem_usageenddate < #{curMonthEndDate}
AND 1=0
GROUP BY co.lineitem_usageaccountid, co.lineitem_productcode, sm.csp_type, co.lineitem_resourceid

SELECT acvd.tenant_id AS accountID , acvd.vm_id AS productID , 'AZURE' AS csp , SUM(acvd.pre_tax_cost) / ${krwPerUsd} AS bill , acvd.resource_id AS resourceID FROM azure_cost_vm_daily acvd INNER JOIN servicegroup_meta sm ON acvd.resource_id COLLATE utf8mb4_unicode_ci = sm.csp_instanceid COLLATE utf8mb4_unicode_ci AND sm.csp_type = 'AZURE'
AND sm.service_cd IN
#{selectedProject}
WHERE DATE_FORMAT(acvd.usage_date, '%Y%m') = #{year_month}
AND 1=0
GROUP BY acvd.tenant_id, acvd.vm_id, acvd.resource_id
UNION ALL
SELECT acr.tenant_id COLLATE utf8mb4_unicode_ci AS accountID , CASE acr.resource_type WHEN 'K8S' THEN 'Azure Kubernetes Service' WHEN 'K8S_NODE' THEN 'Virtual Machines' -- AKS 노드 스케일셋: Invoice 는 청구서 서비스명 그대로(AWS AmazonEC2, GCP Compute Engine, NCP Server 와 같은 기준) WHEN 'OBJECT_STORAGE' THEN 'Storage' ELSE acr.resource_type END COLLATE utf8mb4_unicode_ci AS productID , 'AZURE' AS csp , SUM(acr.pre_tax_cost) / ${krwPerUsd} AS bill , acr.resource_id COLLATE utf8mb4_unicode_ci AS resourceID FROM azure_cost_resource_daily acr INNER JOIN servicegroup_meta sm ON LOWER(acr.resource_id) COLLATE utf8mb4_unicode_ci = LOWER(sm.csp_instanceid) COLLATE utf8mb4_unicode_ci AND sm.csp_type = 'AZURE' AND acr.resource_type != 'OBJECT_STORAGE' -- Object Storage 는 계정 단위 블록(D-4)에서 집계
AND sm.service_cd IN
#{selectedProject}
WHERE DATE_FORMAT(acr.usage_date, '%Y%m') = #{year_month}
AND 1=0
GROUP BY acr.tenant_id, acr.resource_type, acr.resource_id
UNION ALL
SELECT acr.tenant_id COLLATE utf8mb4_unicode_ci AS accountID , 'Storage' COLLATE utf8mb4_unicode_ci AS productID , 'AZURE' AS csp , SUM(acr.pre_tax_cost) / ${krwPerUsd} AS bill , acr.resource_id COLLATE utf8mb4_unicode_ci AS resourceID FROM azure_cost_resource_daily acr WHERE acr.resource_type = 'OBJECT_STORAGE' AND LOWER(acr.resource_name) IN (${azureObjStgAccounts}) AND DATE_FORMAT(acr.usage_date, '%Y%m') = #{year_month} AND EXISTS (SELECT 1 FROM servicegroup_meta smo WHERE smo.csp_type = 'AZURE' AND smo.service_type = 'OBJECT_STORAGE'
AND smo.service_cd IN
#{selectedProject}
)
AND 1=0
GROUP BY acr.tenant_id, acr.resource_id

SELECT raw.billing_account_id AS accountID , raw.service_description AS productID , 'GCP' AS csp , SUM(raw.cost) / ${krwPerUsd} AS bill , raw.csp_instanceid AS resourceID FROM gcp_billing_raw raw INNER JOIN servicegroup_meta sm ON sm.csp_type = 'GCP' AND sm.csp_instanceid COLLATE utf8mb4_uca1400_ai_ci = raw.csp_instanceid
AND sm.service_cd COLLATE utf8mb4_uca1400_ai_ci IN
#{selectedProject}
WHERE raw.invoice_month = #{year_month}
AND 1=0
GROUP BY raw.billing_account_id, raw.service_description, raw.csp_instanceid
